const params=new URLSearchParams(location.search), app=document.querySelector('#app');
let page=params.get('page')||'ring';
let state={size:'Medium',around:16384,across:256,height:160,pattern:'engineered',decay:10,thickness:7,sky:'Atmosphere',sun:'Small',detail:'Medium',seed:'12345',river:false,structures:false,monument:false,paused:false};
const initialState=structuredClone(state);
const names=['Ring','Terrain','Walls','Sky','Preview'];
const button=(label,attrs='')=>`<button ${attrs}>${label}</button>`;
function ring(){return `<div class="stack"><div><h2>Choose your ring size</h2><div class="grid3">${[['Small','2,048 x 128','Strong curve'],['Medium','16,384 x 256','Recommended'],['Large','32,768 x 512','Gentle curve']].map(([n,d,c])=>`<button class="preset ${state.size===n?'selected':''}" data-size="${n}"><strong>${n}${state.size===n?' *':''}</strong><small>${d} blocks</small><small class="${n==='Medium'?'badge':''}">${c}</small></button>`).join('')}</div></div><div><h3>Dimensions <small>in blocks</small></h3><div class="grid3 fields"><label>Circumference<input id="around" type="number" value="${state.around}" step="16"></label><label>Width<input id="across" type="number" value="${state.across}" step="16"></label><label>Wall height<input id="height" type="number" value="${state.height}"></label></div><small>Wall height is measured from the world bottom, not from the terrain.</small></div><div class="note ${state.size==='Small'?'warn':''}" id="size-note">${state.size==='Small'?'Small is experimental. Some portals may need mining to reach.':state.size==='Large'?'Large uses the full Atlas size allowance. Complete generation takes longer.':'Medium offers a visible curve and room to explore.'}</div><details><summary>Size details &amp; generation estimates</summary><p>${(state.around*state.across/256).toLocaleString()} canonical chunks · ${(state.around*state.across).toLocaleString()} Atlas cells<br>Atlas memory: ${(state.around*state.across*12/1048576).toFixed(0)} MiB raw. Generation estimates depend on hardware.<br>Full formulas, playable area and height limits remain available here.</p></details><div><button data-restore>Restore saved settings</button></div></div>`}
function terrain(){return `<h2>Terrain &amp; structures</h2><div class="stack">${[['structures','More structures','Moderately increases eligible landmarks.'],['monument','Ocean monument search','Runs one search on first load. A suitable location is not guaranteed.'],['river','Continuous ring river','Adds the existing seeded river loop.']].map(([key,title,desc])=>`<div class="setting"><div><h3>${title}</h3><p>${desc}${key==='monument'&&state.across<160?'<br><span class="gold">Requires a ring at least 160 blocks wide.</span>':''}</p></div><button class="switch ${state[key]?'selected':''}" data-toggle="${key}" ${key==='monument'&&state.across<160?'disabled':''}>${state[key]?'On':'Off'}</button></div>`).join('')}<div class="note">These settings belong to the world and lock when it is created.</div></div>`}
function walls(){return `<div class="wall-layout"><div><h2>Selected wall sample</h2><img class="wall-photo" src="assets/wall-${state.pattern}.png" alt="RingWorld material, selected wall pattern"><p class="wall-caption">RingWorld / ${state.pattern==='engineered'?'RingWorld Structure':state.pattern==='masonry'?'Masonry':'Gradient'}<br>Sample: 7 blocks thick, 0% decay.<br>Thickness and decay are not shown in this image.</p><label>Style preset<select id="preset"><option>RingWorld</option><option>Weathered</option><option>Ancient</option><option>Escarpment</option><option>Ring alloy</option><option>Overgrown</option><option>Monolith</option><option>Nether</option><option>Obsidian</option><option>Wood</option></select></label><div class="concept-label">Prototype demonstrates the RingWorld material only.</div></div><div class="wall-controls"><label>Material<select id="material"><option>RingWorld</option>${['Weathered stone','Ancient masonry','Natural rock','Ring alloy','Overgrown ruin','Clean monolith','Nether fortress','Obsidian bastion','Timber rampart'].map(x=>`<option disabled>${x} (report only)</option>`).join('')}</select></label><div><label>Pattern</label><div class="pattern">${[['engineered','RingWorld Structure'],['masonry','Masonry'],['gradient','Gradient']].map(([id,n])=>button(n,`data-pattern="${id}" class="${state.pattern===id?'selected':''}"`)).join('')}</div></div><label>Thickness <small>1-32 blocks</small><input id="thickness" type="number" min="1" max="32" value="${state.thickness}"></label><label>Decay <small>0-100%</small><input id="decay" type="number" min="0" max="100" value="${state.decay}"></label></div></div>`}
function sky(){return `<div class="stack"><div><h2>Backdrop</h2><div class="grid3">${['Atmosphere','Night','Void'].map(n=>`<button class="sky-choice ${state.sky===n?'selected':''}" data-sky="${n}"><div class="skybox ${n.toLowerCase()}">${n==='Atmosphere'?'<span class="sun"></span>':''}</div>${n}${state.sky===n?' *':''}<br><small>${n==='Atmosphere'?'Open blue sky':n==='Night'?'Dark, starry sky':'Empty backdrop'}</small></button>`).join('')}</div><div class="concept-label">Schematic previews for this proposal; not in-game captures.</div></div><div><h2>Sun</h2><div class="segmented">${['Small','Large','None'].map(n=>button(n,`data-sun="${n}" class="${state.sun===n?'selected':''}"`)).join('')}</div></div><div class="note">Changes the sky appearance for everyone in this world.<br>Time and gameplay are unchanged.</div></div>`}
function map(){let cells='';for(let y=0;y<32;y++)for(let x=0;x<64;x++){let v=Math.sin(x*.18)+Math.cos(y*.29)+.5*Math.sin(x*.49+y*.21),c=v<-.65?'#477d9d':v<-.4?'#b3ac78':v>.95?'#a2aaa2':v>.6?'#77877b':v>.15?'#647b47':'#849350';cells+=`<rect x="${x*8}" y="${y*8}" width="8" height="8" fill="${c}"/>`}return `<svg class="map" viewBox="0 0 512 256" role="img" aria-label="Illustrative top-down terrain, not a seed result">${cells}</svg>`}
function preview(){return `<div class="seedrow"><label>World seed<input id="seed" value="${state.seed}" placeholder="Blank for random"></label><button data-reroll>Reroll</button></div><div class="mapframe">${map()}<span class="maplabel">512 x 256 blocks · illustrative terrain</span></div><div class="overview"><div class="row spread"><small>Full ring overview · selected area outlined</small><div class="row"><button data-pan="-1">&lt;</button><button data-pan="1">&gt;</button></div></div><div class="overview-strip"><span class="window"></span></div><small id="preview-note">Approximate terrain only. No structures, caves or save created.</small></div>`}
function generation(){return `<div class="stack"><div><h2>Entire-ring generation</h2><small>Medium · 16,384 x 256 blocks</small></div><div class="card"><div class="row spread"><div class="metric">42%</div><span id="gen-state">${state.paused?'Paused':'Generating chunks'}</span></div><div class="progress"><span></span></div><div class="row spread"><small>6,881 / 16,384 chunks</small><small>${state.paused?'':'About 9 min left'}</small></div><div class="row" style="margin-top:12px"><button data-pause>${state.paused?'Resume':'Pause'}</button><button data-stop>Stop generation...</button></div></div><small>You can return to the game while generation continues.<br>Keep the world or server running. Generated chunks are saved.</small><details><summary>Technical details</summary><p>Elapsed time · chunk rate · Atlas progress · preview texture stages<br>Build and worldgen identity · complete error details</p></details><div class="concept-label">Example progress values; not a live server status.</div></div>`}
function display(){return `<div class="stack"><div><h2>Distant terrain detail</h2><p class="muted">Changes how the Atlas looks on your computer.</p></div><div class="grid3">${[['Low','Lightest'],['Medium','Default'],['High','Finest detail']].map(([n,desc])=>`<button class="preset ${state.detail===n?'selected':''}" data-detail="${n}"><strong>${n}${state.detail===n?' *':''}</strong><small>${desc}</small></button>`).join('')}</div><div class="note">Applies immediately. No world regeneration needed.<br>Other players can choose a different setting.</div><details><summary>Detail information</summary><p>Low: 8-block samples / 8-block mesh step.<br>Medium: 2-block samples / 4-block mesh step.<br>High: 1-block samples / 1-block mesh step.<br>Effective resolution also depends on ring size and GPU limits.</p></details><small>The full source Atlas remains one sample per block.</small></div>`}
function returned(){return `<div class="return-panel stack"><h2>RingWorld settings ready</h2><p class="muted">Returns to Minecraft's Create World screen.</p><div class="card summary-list"><span>Ring</span><span>${state.size} · ${state.around.toLocaleString()} x ${state.across}</span><span>Walls</span><span>RingWorld</span><span>Backdrop / sun</span><span>${state.sky} / ${state.sun}</span><span>Seed</span><span>${state.seed||'Random'}</span></div><div class="note">No world has been created.<br>Use Minecraft's Create World button when ready.</div><button data-page="ring">Edit RingWorld settings</button><small>Proposed vanilla entry label: RingWorld: ${state.size}...</small></div>`}
const pages={ring,terrain,walls,sky,preview,generation,display,returned};
function render(){let local=['generation','display'].includes(page);app.innerHTML=`<div class="shell"><header class="head"><h1>${local?'RingWorld':'Create a RingWorld'}</h1><small>${local?'Current world':'New world settings'}<br>${local?'':`${state.size} · ${state.around.toLocaleString()} x ${state.across}`}</small></header>${page==='returned'?'':`<nav class="tabs" aria-label="RingWorld pages">${(local?['Generation','Display']:names).map(n=>button(n,`data-page="${n.toLowerCase()}" class="${page===n.toLowerCase()?'selected':''}" aria-current="${page===n.toLowerCase()?'page':'false'}"`)).join('')}</nav>`}<main class="body">${(pages[page]||ring)()}</main><footer class="footer"><small>${local?'This screen does not pause the world.':'Settings lock when the world is created.'}</small><div class="buttons">${local?button('Return to game','data-return'):page==='returned'?button('Back to proposal','data-page="ring"'):button('Cancel','data-cancel')+button('Apply settings','class="primary" data-apply')}</div></footer></div>`;bind()}
function dialog(title,body,confirm,fn){let d=document.createElement('div');d.className='dialog';d.setAttribute('role','dialog');d.setAttribute('aria-label',title);d.innerHTML=`<div class="dialog-card"><h2>${title}</h2><p>${body}</p><div class="buttons"><button data-back>Back</button><button data-confirm class="primary">${confirm}</button></div></div>`;app.append(d);d.querySelector('[data-back]').onclick=()=>d.remove();d.querySelector('[data-confirm]').onclick=()=>{d.remove();fn()};d.querySelector('[data-back]').focus()}
function bind(){app.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;render()});app.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{state.size=b.dataset.size;[state.around,state.across]=({Small:[2048,128],Medium:[16384,256],Large:[32768,512]})[state.size];state.height=160;if(state.across<160)state.monument=false;render()});app.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{state[b.dataset.toggle]=!state[b.dataset.toggle];render()});for(let key of ['pattern','sky','sun','detail'])app.querySelectorAll(`[data-${key}]`).forEach(b=>b.onclick=()=>{state[key]=b.dataset[key];render()});for(let key of ['around','across','height','thickness','decay','seed']){let el=app.querySelector('#'+key);if(el)el.oninput=()=>{state[key]=key==='seed'?el.value:Number(el.value);if(['around','across','height'].includes(key))state.size='Custom'}}app.querySelector('[data-apply]')?.addEventListener('click',()=>{if(state.around*state.across>16777216){page='ring';render();document.querySelector('#size-note').className='note error';document.querySelector('#size-note').textContent='Ring Larger than Max Atlas Size: reduce Circumference or Width to stay at or below 16,777,216 Atlas cells.';document.querySelector('#around').focus();return}page='returned';render()});app.querySelector('[data-cancel]')?.addEventListener('click',()=>dialog('Discard changes?','Discard changes to the ring settings and world seed? Your previous settings will be kept.','Discard',()=>{state=structuredClone(initialState);page='returned';render()}));app.querySelector('[data-restore]')?.addEventListener('click',()=>dialog('Restore saved settings?','Replace this draft with your previously saved RingWorld settings.','Restore',()=>{state=structuredClone(initialState);render()}));app.querySelector('[data-reroll]')?.addEventListener('click',()=>{state.seed=String(Math.floor(Math.random()*999999999));render();document.querySelector('#preview-note').textContent='Seed changed in mockup. Terrain is illustrative, not regenerated.'});let offset=31;app.querySelectorAll('[data-pan]').forEach(b=>b.onclick=()=>{offset=(offset+Number(b.dataset.pan)*3.125+96.875)%96.875;document.querySelector('.window').style.left=offset+'%';document.querySelector('#preview-note').textContent='Overview navigation demo. Detailed terrain remains illustrative.'});app.querySelector('[data-pause]')?.addEventListener('click',()=>{state.paused=!state.paused;render()});app.querySelector('[data-stop]')?.addEventListener('click',()=>dialog('Stop generation?','Already generated chunks remain saved. This stops the current generation job.','Stop',()=>{state.paused=true;render();document.querySelector('#gen-state').textContent='Stopped'}));app.querySelector('[data-return]')?.addEventListener('click',()=>dialog('Return to game','In Minecraft, this closes the screen and resumes play. This prototype is only a design preview.','Close preview',()=>{}));app.querySelector('#preset')?.addEventListener('change',()=>dialog('Style presets','The implemented menu would apply material, pattern, thickness and decay together. This review prototype only renders the RingWorld material.','OK',()=>{}))}
render();if(params.get('modal')==='start')dialog('Generate entire ring?','Generates and saves 16,384 terrain chunks. This takes time and uses disk space. You can pause the job and return to playing.','Generate',()=>{});if(params.get('modal')==='stop')dialog('Stop generation?','Already generated chunks remain saved. This stops the current generation job.','Stop',()=>{});
